rule "parse School Bell structured syslog"
when
  has_field("message") &&
  has_field("application_name") &&
  to_string($message.application_name) == "school-bell"
then
  let json_message = regex_replace(
    pattern: "^[^{]*",
    value: to_string($message.message),
    replacement: ""
  );
  let parsed = parse_json(json_message);
  let fields = to_map(parsed);
  set_fields(fields: fields, prefix: "sb_");
end
